// Headline strip: On a statin, Average of all places, Not on a statin.
const root = rpt.mount('.rpt-sta-head');
if (!root) { return; }
const { fmt, num, yes, pct } = rpt;
const r = rpt.rows('A')[0];
const L = ['On a statin', 'Average of all places', 'Not on a statin'];
if (!r) { root.innerHTML = '<div class="rpt-strip3">' + L.map((l) => col('—', '', l, rpt.NO_DATA)).join('') + '</div>'; return; }
const N = num(r.eligible_n) || 0;
const when = 'Eligible at the end of ' + rpt.month(rpt.reportingMonth());
const first = !N ? col('—', '', L[0], 'No eligible patients here.')
  : yes(r.too_few) ? col('Too few patients', '', L[0], rpt.needAtLeast(r.min_eligible, N), '', true)
  : col(pct(r.on_statin_pct), yes(r.flag) ? 'var(--flag-bar)' : 'var(--controlled)', L[0],
    [fmt(r.on_statin_n) + ' of ' + fmt(N) + ' eligible patients', when]);
const avg = num(r.avg_pct) === null ? col('—', '', L[1], rpt.NO_DATA)
  : col(pct(r.avg_pct), '#9B7FD4', L[1], [fmt(r.avg_n) + ' of ' + fmt(r.avg_d) + ' eligible patients, all places together', when]);
root.innerHTML = '<div class="rpt-strip3">' + first + avg
  + col(fmt(r.not_on_statin_n), 'var(--no-visit)', L[2], ['Eligible patients with no statin on their latest prescription', 'They may need a review.']) + '</div>';

