// Patients to review: eligible patients not on a statin, facility level only. Overdue list pattern:
// reason chips with counts, search by name or Patient ID, 10 rows per page, pager. No download.
const root = rpt.mount('.rpt-pl');
if (!root) { return; }
const { esc, fmt, num } = rpt;
const all = rpt.rows('A');
const head = all[0] || {};
const level = num(head.level) !== null ? num(head.level) : num(rpt.v('selected_level')) || 0;
// Above facility level the row is hidden (conditional rendering); if shown, a grey line with the next step (UX-21).
if (rpt.orgUnit() === '0' || level < 3) {
  root.innerHTML = rpt.info(rpt.esc(rpt.PICK_FACILITY));
  return;
}
const rows = all.filter((r) => r.patient_id != null);
const total = num(head.not_on_statin_n);
const place = rpt.place(head.place);
const title = '<h3 class="rpt-pl-title">Patients to review</h3>'
  + '<div class="rpt-pl-head">' + fmt(total === null ? rows.length : total) + ' eligible patients not on a statin at ' + esc(place) + '</div>';
// Graphs-only teams see the count, never names (the query joins no patients for them).
if (rpt.v('isPatientsAllowed') !== '1') { root.innerHTML = title + rpt.info('Patient names need patient-level access. Ask your admin.'); return; }
if (!rows.length) { root.innerHTML = title + rpt.noData('No patients to review here.'); return; }

const PAGE = 10;
const REASONS = ['Diabetes', 'Heart attack or stroke', 'Both'];
// Most recent visit first: these patients are the easiest to reach at their next visit.
const time = (r) => { const d = rpt.toDate(r.last_visit_date); return d ? d.getTime() : 0; };
rows.sort((a, b) => time(b) - time(a) || String(a.patient_name).localeCompare(String(b.patient_name)));
const state = { reason: 'All', q: '', page: 0 };
const visible = () => {
  const q = state.q.trim().toLowerCase();
  return rows.filter((r) => state.reason === 'All' || r.reason_eligible === state.reason)
    .filter((r) => !q || [r.patient_name, r.patient_id].some((v) => String(v || '').toLowerCase().includes(q)));
};
const COLS = [
  ['Patient', (r) => esc(r.patient_name) + '<div class="rpt-pl-id">' + esc(r.patient_id) + '</div>'],
  ['Age', (r) => esc(r.age), 'num'],
  ['Why eligible', (r) => esc(r.reason_eligible)],
  ['Last visit', (r) => esc(rpt.day(r.last_visit_date))],
];
const cls = (c) => (c ? ' class="' + c + '"' : '');
const renderChips = () => {
  const n = (g) => rows.filter((r) => r.reason_eligible === g).length;
  root.querySelector('.rpt-chips').innerHTML = [['All', rows.length]].concat(REASONS.map((g) => [g, n(g)]))
    .map(([g, c]) => '<button type="button" class="rpt-chip' + (state.reason === g ? ' on' : '') + '" data-reason="' + esc(g) + '" aria-pressed="' + (state.reason === g) + '">'
      + esc(g) + ': ' + fmt(c) + '</button>').join('');
};
const renderBody = () => {
  const list = visible();
  const pages = Math.max(1, Math.ceil(list.length / PAGE));
  state.page = Math.min(Math.max(state.page, 0), pages - 1);
  const shown = list.slice(state.page * PAGE, (state.page + 1) * PAGE);
  root.querySelector('tbody').innerHTML = shown.length
    ? shown.map((r) => '<tr>' + COLS.map(([, cell, c], i) => (i ? '<td' + cls(c) + '>' + cell(r) + '</td>' : '<th scope="row">' + cell(r) + '</th>')).join('') + '</tr>').join('')
    : '<tr><td class="rpt-empty" colspan="' + COLS.length + '">No patients match these filters.</td></tr>';
  root.querySelector('.rpt-pager').innerHTML = list.length
    ? '<button type="button" data-page="-1"' + (state.page ? '' : ' disabled') + ' aria-label="Previous page">‹</button>'
      + '<span>' + fmt(state.page * PAGE + 1) + '–' + fmt(state.page * PAGE + shown.length) + ' of ' + fmt(list.length) + '</span>'
      + '<button type="button" data-page="1"' + (state.page < pages - 1 ? '' : ' disabled') + ' aria-label="Next page">›</button>'
    : '';
  renderChips();
};
root.innerHTML = title
  + '<div class="rpt-chips" role="group" aria-label="Filter by why eligible"></div>'
  + '<div class="rpt-pl-tools"><input type="search" class="rpt-pl-q" placeholder="Search name or Patient ID" aria-label="Search patients"></div>'
  + '<div class="rpt-wrap"><table class="rpt-table"><caption class="rpt-sr">Eligible patients not on a statin, most recent visit first.</caption><thead><tr>'
  + COLS.map(([h, , c]) => '<th scope="col"' + cls(c) + '>' + h + '</th>').join('')
  + '</tr></thead><tbody></tbody></table></div><div class="rpt-pager"></div>';
renderBody();
root.addEventListener('input', (e) => {
  if (e.target.classList.contains('rpt-pl-q')) { state.q = e.target.value; state.page = 0; renderBody(); }
});
root.addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b || !root.contains(b)) { return; }
  if (b.dataset.reason) { state.reason = b.dataset.reason; state.page = 0; renderBody(); const f = root.querySelector('[data-reason="' + b.dataset.reason + '"]'); if (f) { f.focus(); } return; }
  if (b.dataset.page) { state.page += Number(b.dataset.page); renderBody(); const f = root.querySelector('[data-page="' + b.dataset.page + '"]'); if (f && !f.disabled) { f.focus(); } }
});

